package edgefleet

import (
	"errors"
	"strings"
	"testing"
)

// Regression safeguards for the ordering between record content validation
// and the idle-partition resume judgement in partitioned sliding mode. The
// history is slidingIdleResumeFixtureLines (window 1000, slide 600, two
// partitions, key "sensor-a"): partition 0's event at 700/2 lands in
// [0,1000) and [600,1600), partition 1's event at 1000/3 lands only in
// [600,1600); after watermarks 2000 on partition 0 and 1000 on partition 1,
// [0,1000) is already closed (count 1, sum 2) while [600,1600) stays open.
// Partition 0 then declares idle on physical line 6: the effective
// watermark stays 1000 (partition 1 is active there), but partition 0's own
// old watermark remains 2000.
//
// The next watermark record (physical line 8) is the partition's resume
// record, and the ordering under protection is:
//
//  1. The "time" field must first parse as a non-negative signed 64-bit
//     integer -- missing, string-typed, negative or out-of-range is the
//     record's first error even when the same record's "partition" field is
//     also wrong, regardless of the two fields' textual order in the JSON.
//  2. Only after time is legal may "partition" be read and range-checked;
//     a missing, string-typed or out-of-range partition is the reported
//     problem even when that legal time (1600) is below the partition's own
//     old watermark 2000.
//  3. Only with both fields legal do the resume bounds apply, in their
//     existing order: the partition's own previous watermark first (so 1600
//     fails against 2000) and never the effective watermark 1000.
//
// Every failure is the existing *InputError naming physical line 8 (blank
// physical lines 5 and 7 count) with a distinguishable reason. It must not
// become a late-event notice, the window already emitted stays exactly as
// published, and the dead records after it (a watermark that would close
// [600,1600), then an event that would log a late notice) take no effect.

// slidingIdleResumeDeadSuffix are the records that must stay completely dead
// after a fatal resume-record error on physical line 8:
//
//	line 9: partition 1 watermark 1600 -- would close [600,1600) if reached
//	line 10: partition 1 event time=999 -- would log a late notice if reached
func slidingIdleResumeDeadSuffix() []string {
	return []string{
		`{"type":"watermark","time":1600,"partition":1}`,
		`{"type":"event","key":"sensor-a","time":999,"value":1,"partition":1}`,
	}
}

var slidingIdleResumeWantFirstWindow = `{"key":"sensor-a","start":0,"end":1000,"count":1,"sum":2}` + "\n"

// assertResumeFieldError checks the common contract of every malformed resume
// record: an *InputError (never an *OutputError) on physical line 8, a reason
// naming wantField and stating wantCause, with no trace of the other field,
// the resume-bound comparisons, a late-event skip or window accumulation;
// stderr stays empty and stdout keeps only the window closed before line 8.
func assertResumeFieldError(t *testing.T, stdout, stderr string, err error, wantField, wantCause string) {
	t.Helper()
	if err == nil {
		t.Fatalf("a malformed resume record must fail fatally; got nil, stdout=%q stderr=%q", stdout, stderr)
	}
	var inputErr *InputError
	if !errors.As(err, &inputErr) {
		t.Fatalf("want *InputError, got %T: %v", err, err)
	}
	var outputErr *OutputError
	if errors.As(err, &outputErr) {
		t.Fatalf("a malformed record must not be reported as an output failure: %v", err)
	}
	if inputErr.Line != 8 {
		t.Errorf("InputError.Line = %d, want 8 (blank physical lines 5 and 7 count)", inputErr.Line)
	}
	if !strings.Contains(inputErr.Reason, wantField) {
		t.Errorf("reason %q must name field %s", inputErr.Reason, wantField)
	}
	if !strings.Contains(inputErr.Reason, wantCause) {
		t.Errorf("reason %q must state the concrete cause %q", inputErr.Reason, wantCause)
	}
	// Field validation happens before any idle-resume state is consulted:
	// neither resume bound may appear in the reason.
	for _, sub := range []string{"resume watermark", "previous watermark", "effective watermark"} {
		if strings.Contains(inputErr.Reason, sub) {
			t.Errorf("a field error must be reported before the resume bounds, reason %q mentions %q", inputErr.Reason, sub)
		}
	}
	if strings.Contains(err.Error(), "late event") {
		t.Errorf("an invalid resume record must not be described as a late-event skip: %q", err.Error())
	}
	if stderr != "" {
		t.Errorf("a rejected resume record and its dead suffix must write no late-event notice, got %q", stderr)
	}
	if stdout != slidingIdleResumeWantFirstWindow {
		t.Errorf("window output mismatch:\n got: %q\nwant: %q", stdout, slidingIdleResumeWantFirstWindow)
	}
}

// TestSlidingIdleResumeInvalidTimeFailsBeforePartition covers every invalid
// time shape on a resume record. Each record also carries an invalid
// partition (out of range or string-typed) to prove the time field is
// settled first: missing time, a string time, a negative time and times
// beyond either end of signed 64-bit range are each the concrete first
// error on physical line 8.
func TestSlidingIdleResumeInvalidTimeFailsBeforePartition(t *testing.T) {
	cases := []struct {
		name      string
		record    string
		wantField string
		wantCause string
	}{
		{
			name:      "time missing while partition is out of range",
			record:    `{"type":"watermark","partition":9}`,
			wantField: `"time"`,
			wantCause: `missing required integer field "time"`,
		},
		{
			name:      "time written as string while partition is also a string",
			record:    `{"type":"watermark","time":"1600","partition":"0"}`,
			wantField: `"time"`,
			wantCause: `field "time" must be a signed 64-bit integer, got "1600"`,
		},
		{
			name:      "time negative while partition is out of range",
			record:    `{"type":"watermark","time":-1,"partition":9}`,
			wantField: `"time"`,
			wantCause: `field "time" must be a non-negative integer, got -1`,
		},
		{
			name:      "time above signed 64-bit range while partition is out of range",
			record:    `{"type":"watermark","time":9223372036854775808,"partition":9}`,
			wantField: `"time"`,
			wantCause: `field "time" integer out of signed 64-bit range: 9223372036854775808`,
		},
		{
			name:      "time below signed 64-bit range while partition is out of range",
			record:    `{"type":"watermark","time":-9223372036854775809,"partition":9}`,
			wantField: `"time"`,
			wantCause: `field "time" integer out of signed 64-bit range: -9223372036854775809`,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			lines := append(slidingIdleResumeFixtureLines(), tc.record)
			lines = append(lines, slidingIdleResumeDeadSuffix()...)
			stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
			assertResumeFieldError(t, stdout, stderr, err, tc.wantField, tc.wantCause)
			// The other field is broken too; it must not be the named one.
			if inputErr := inputErrorFrom(t, err); strings.Contains(inputErr.Reason, `"partition"`) {
				t.Errorf("time must be checked before partition, reason = %q", inputErr.Reason)
			}
		})
	}
}

// TestSlidingIdleResumeFieldOrderDoesNotChangeFirstError proves the first
// error is fixed by validation order (time, then partition, then resume
// bounds), not by the order the two fields happen to be written in the JSON.
// Swapping the textual order must yield the identical physical line and
// reason, both when time is the broken field and when a legal-but-low time
// accompanies a broken partition.
func TestSlidingIdleResumeFieldOrderDoesNotChangeFirstError(t *testing.T) {
	cases := []struct {
		name      string
		timeFirst string
		partFirst string
		wantField string
		wantCause string
	}{
		{
			name:      "string time and string partition",
			timeFirst: `{"type":"watermark","time":"1600","partition":"0"}`,
			partFirst: `{"type":"watermark","partition":"0","time":"1600"}`,
			wantField: `"time"`,
			wantCause: `field "time" must be a signed 64-bit integer, got "1600"`,
		},
		{
			name:      "negative out-of-range time and out-of-range partition",
			timeFirst: `{"type":"watermark","time":-1,"partition":9}`,
			partFirst: `{"type":"watermark","partition":9,"time":-1}`,
			wantField: `"time"`,
			wantCause: `field "time" must be a non-negative integer, got -1`,
		},
		{
			name:      "legal low time with string partition",
			timeFirst: `{"type":"watermark","time":1600,"partition":"0"}`,
			partFirst: `{"type":"watermark","partition":"0","time":1600}`,
			wantField: `"partition"`,
			wantCause: `field "partition" must be a signed 64-bit integer, got "0"`,
		},
		{
			name:      "legal low time with out-of-range partition",
			timeFirst: `{"type":"watermark","time":1600,"partition":9}`,
			partFirst: `{"type":"watermark","partition":9,"time":1600}`,
			wantField: `"partition"`,
			wantCause: `field "partition" must be an integer in range [0,2), got 9`,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			first := runResumeFieldError(t, tc.timeFirst)
			second := runResumeFieldError(t, tc.partFirst)
			if first.Line != 8 || second.Line != 8 {
				t.Errorf("line numbers = %d and %d, want 8 for both field orders", first.Line, second.Line)
			}
			if first.Reason != second.Reason {
				t.Errorf("field order changed the first error:\n time-first: %q\npart-first: %q", first.Reason, second.Reason)
			}
			if !strings.Contains(first.Reason, tc.wantField) {
				t.Errorf("reason %q must name %s", first.Reason, tc.wantField)
			}
			if !strings.Contains(first.Reason, tc.wantCause) {
				t.Errorf("reason %q must state %q", first.Reason, tc.wantCause)
			}
		})
	}
}

// TestSlidingIdleResumeInvalidPartitionAfterLegalTime covers the second
// stage: once time parses legally, partition problems are reported even
// though the time 1600 is below partition 0's own old watermark 2000. The
// resume-bound comparison must not run first and "rescue" the record into a
// resume-watermark error.
func TestSlidingIdleResumeInvalidPartitionAfterLegalTime(t *testing.T) {
	cases := []struct {
		name      string
		record    string
		wantCause string
	}{
		{
			name:      "partition missing",
			record:    `{"type":"watermark","time":1600}`,
			wantCause: `missing required integer field "partition"`,
		},
		{
			name:      "partition written as string",
			record:    `{"type":"watermark","time":1600,"partition":"0"}`,
			wantCause: `field "partition" must be a signed 64-bit integer, got "0"`,
		},
		{
			name:      "partition above configured range",
			record:    `{"type":"watermark","time":1600,"partition":9}`,
			wantCause: `field "partition" must be an integer in range [0,2), got 9`,
		},
		{
			name:      "partition negative",
			record:    `{"type":"watermark","time":1600,"partition":-1}`,
			wantCause: `field "partition" must be an integer in range [0,2), got -1`,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			lines := append(slidingIdleResumeFixtureLines(), tc.record)
			lines = append(lines, slidingIdleResumeDeadSuffix()...)
			stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
			assertResumeFieldError(t, stdout, stderr, err, `"partition"`, tc.wantCause)
			if inputErr := inputErrorFrom(t, err); strings.Contains(inputErr.Reason, `"time"`) {
				t.Errorf("time 1600 is legal and must not be blamed: %q", inputErr.Reason)
			}
		})
	}
}

// TestSlidingIdleResumeLegalFieldsFailsAgainstOwnOldWatermark is the third
// stage: with both fields legal the resume bounds apply, and the partition's
// own previous watermark (2000) is the one violated by time 1600 -- not the
// effective watermark 1000, which 1600 already clears. This is checked with
// both JSON field orders; the dead suffix must neither close [600,1600) nor
// produce a late-event notice.
func TestSlidingIdleResumeLegalFieldsFailsAgainstOwnOldWatermark(t *testing.T) {
	for _, record := range []string{
		`{"type":"watermark","time":1600,"partition":0}`,
		`{"type":"watermark","partition":0,"time":1600}`,
	} {
		lines := append(slidingIdleResumeFixtureLines(), record)
		lines = append(lines, slidingIdleResumeDeadSuffix()...)
		stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
		if err == nil {
			t.Fatalf("resume at 1600 must fail against partition 0's old watermark 2000; got nil, stdout=%q", stdout)
		}
		var inputErr *InputError
		if !errors.As(err, &inputErr) {
			t.Fatalf("want *InputError, got %T: %v", err, err)
		}
		if inputErr.Line != 8 {
			t.Errorf("InputError.Line = %d, want 8", inputErr.Line)
		}
		for _, sub := range []string{
			"resume watermark 1600",
			"partition 0",
			"previous watermark 2000",
		} {
			if !strings.Contains(inputErr.Reason, sub) {
				t.Errorf("reason %q must contain %q", inputErr.Reason, sub)
			}
		}
		if strings.Contains(inputErr.Reason, "effective watermark 1000") {
			t.Errorf("the violated bound must be the partition's own old watermark, not the effective 1000: %q", inputErr.Reason)
		}
		if stderr != "" {
			t.Errorf("no late-event notice may be written, got %q", stderr)
		}
		if stdout != slidingIdleResumeWantFirstWindow {
			t.Errorf("the closed window stays and [600,1600) must not be flushed by the dead suffix:\n got: %q\nwant: %q", stdout, slidingIdleResumeWantFirstWindow)
		}
	}
}

// TestSlidingIdleResumeAtOldWatermarkWaitsForOtherPartition pins the legal
// boundary: resuming partition 0 exactly at its own old watermark 2000
// succeeds while partition 1 still pins the effective watermark at 1000, so
// the resume itself emits nothing -- [600,1600) must not close early and the
// already closed [0,1000) must not be re-emitted. The window closes only
// once partition 1 advances to 1600, merging the two pre-idle events
// (count 2, sum 5, no partition field); a later fast-partition watermark
// must not re-emit closed windows or flush still-open ones.
func TestSlidingIdleResumeAtOldWatermarkWaitsForOtherPartition(t *testing.T) {
	// Truncated run: the resume record is the final record.
	hold := append(slidingIdleResumeFixtureLines(),
		`{"type":"watermark","time":2000,"partition":0}`, // line 8: resume at the old watermark
	)
	stdout, stderr, err := runPartitionedSliding(t, strings.Join(hold, "\n"), 1000, 600, 2)
	if err != nil {
		t.Fatalf("resume exactly at the partition's old watermark must succeed: %v", err)
	}
	if stderr != "" {
		t.Fatalf("resume at the boundary must produce no notice, got %q", stderr)
	}
	if stdout != slidingIdleResumeWantFirstWindow {
		t.Fatalf("partition 1 still at 1000 must hold [600,1600) open after the resume:\n got: %q\nwant: %q", stdout, slidingIdleResumeWantFirstWindow)
	}

	// Full run: partition 1 catches up, then partition 0 jumps ahead.
	lines := append(hold,
		`{"type":"watermark","time":1600,"partition":1}`, // line 9: effective = 1600, closes [600,1600)
		`{"type":"watermark","time":5000,"partition":0}`, // line 10: min stays 1600; nothing new
	)
	stdout, stderr, err = runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
	if err != nil {
		t.Fatalf("the catch-up sequence must succeed: %v", err)
	}
	if stderr != "" {
		t.Fatalf("the boundary sequence must produce no late notice, got %q", stderr)
	}
	want := strings.Join([]string{
		`{"key":"sensor-a","start":0,"end":1000,"count":1,"sum":2}`,
		// Only the two pre-idle events: 700/2 belongs to both windows,
		// 1000/3 belongs only to this one. No post-resume event is sent.
		`{"key":"sensor-a","start":600,"end":1600,"count":2,"sum":5}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
	// Each closed window appears exactly once; later windows stay open.
	if n := strings.Count(stdout, `"start":0,"end":1000`); n != 1 {
		t.Errorf("[0,1000) emitted %d times, want exactly 1", n)
	}
	if n := strings.Count(stdout, `"start":600,"end":1600`); n != 1 {
		t.Errorf("[600,1600) emitted %d times, want exactly 1", n)
	}
	if strings.Contains(stdout, `"start":1200`) {
		t.Errorf("[1200,2200) is still open at end of input and must never be emitted: %q", stdout)
	}
	got := decodeAggregateResults(t, stdout)
	wantRows := []AggregateResult{
		{Key: "sensor-a", Start: 0, End: 1000, Count: 1, Sum: 2},
		{Key: "sensor-a", Start: 600, End: 1600, Count: 2, Sum: 5},
	}
	if len(got) != len(wantRows) {
		t.Fatalf("got %d rows, want %d: %v", len(got), len(wantRows), got)
	}
	for i := range wantRows {
		if got[i] != wantRows[i] {
			t.Errorf("row %d = %+v, want %+v", i, got[i], wantRows[i])
		}
	}
}

// runResumeFieldError runs the shared history plus the given line-8 resume
// record (no dead suffix needed when only the error is compared) and returns
// the *InputError, failing the test on any other outcome.
func runResumeFieldError(t *testing.T, record string) *InputError {
	t.Helper()
	lines := append(slidingIdleResumeFixtureLines(), record)
	_, _, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
	return inputErrorFrom(t, err)
}

// inputErrorFrom extracts the *InputError from err, failing the test when the
// run did not produce one.
func inputErrorFrom(t *testing.T, err error) *InputError {
	t.Helper()
	if err == nil {
		t.Fatalf("expected an *InputError, got nil")
	}
	var inputErr *InputError
	if !errors.As(err, &inputErr) {
		t.Fatalf("want *InputError, got %T: %v", err, err)
	}
	return inputErr
}

package edgefleet

import (
	"errors"
	"math"
	"strings"
	"testing"
)

// Regression safeguards for the ordering between record validation and the
// late-event judgement in partitioned sliding mode (window 1000, slide 600,
// two partitions whose watermarks already differ and whose effective
// (minimum) watermark is established):
//
//   - A record whose own fields are invalid must fail with *InputError at its
//     physical line even when its event time is strictly below the effective
//     watermark (and still inside an unclosed overlapping window). It must
//     never be absorbed as a normal late-event skip, and it must never be
//     blamed on a window cumulative-sum overflow that the record never reached.
//   - A record with every field legal is judged late against the EFFECTIVE
//     watermark and skipped with exactly one notice, changing no window. Its
//     value may be a legal integer that would overflow the open window's
//     accumulated sum: the skip still wins over the sum check.
//   - An event with time exactly equal to the effective watermark is not late:
//     it joins the window containing it and the window closes with the right
//     count and sum once the minimum watermark allows. The fast partition's
//     own, larger watermark can neither judge lateness nor close windows by
//     itself.
//
// Blank physical lines count toward the line number in every scenario.

// lateFieldOrderPrefix builds the shared history (window 1000, slide 600,
// partitions 2):
//
//	line 1: blank (physical lines count)
//	line 2: event k time=900 value=7 partition 0 -> [0,1000) and [600,1600)
//	line 3: watermark 5000 partition 0           -> fast partition races ahead
//	line 4: watermark 1000 partition 1           -> effective min = 1000;
//	                                               closes only [0,1000);
//	                                               [600,1600) stays open
//	line 5: blank
//
// so a time=999 record on line 6 is strictly below the effective watermark
// 1000 (yet still inside the open [600,1600)), and partition 0's own
// watermark 5000 is not the value that judges it.
func lateFieldOrderPrefix() []string {
	return []string{
		``, // line 1 blank
		`{"type":"event","key":"k","time":900,"value":7,"partition":0}`, // line 2
		`{"type":"watermark","time":5000,"partition":0}`,                // line 3
		`{"type":"watermark","time":1000,"partition":1}`,                // line 4: effective = 1000
		``, // line 5 blank
	}
}

// lateFieldOrderSuffix are the records that must be completely dead after a
// fatal record error on line 6:
//
//	line 6 would hold the bad record (supplied by the caller)
//	line 7: legal event at time == watermark 1000, would enter [600,1600)
//	line 8: legal time=998 event, would log another late notice if reached
//	line 9: watermark 1600 partition 1, would close [600,1600) if reached
func lateFieldOrderSuffix() []string {
	return []string{
		`{"type":"event","key":"k","time":1000,"value":3,"partition":1}`, // line 7
		`{"type":"event","key":"k","time":998,"value":1,"partition":1}`,  // line 8 late if reached
		`{"type":"watermark","time":1600,"partition":1}`,                 // line 9
	}
}

var lateFieldOrderWantFirstWindow = `{"key":"k","start":0,"end":1000,"count":1,"sum":7}` + "\n"

// TestSlidingPartitionInvalidLateRecordIsInputError covers every invalid
// field shape on an event that is unambiguously late (time 999 < effective
// watermark 1000) and still inside the open [600,1600): value missing, value
// written as a string, value outside signed 64-bit range, and (with a legal
// value) partition missing or out of the configured range. Each must be an
// *InputError on physical line 6 naming the offending field and the concrete
// reason -- not a late-event skip, not a cumulative sum overflow. Earlier
// fully written output is retained, the open window is not retroactively
// emitted, and no later result or late notice may appear.
func TestSlidingPartitionInvalidLateRecordIsInputError(t *testing.T) {
	cases := []struct {
		name      string
		record    string
		wantField string // the field name the reason must quote
		wantCause string // a distinctive substring of the concrete reason
	}{
		{
			name:      "value missing",
			record:    `{"type":"event","key":"k","time":999,"partition":1}`,
			wantField: `"value"`,
			wantCause: `missing required integer field "value"`,
		},
		{
			name:      "value written as string",
			record:    `{"type":"event","key":"k","time":999,"value":"oops","partition":1}`,
			wantField: `"value"`,
			wantCause: `field "value" must be a signed 64-bit integer, got "oops"`,
		},
		{
			name:      "value above signed 64-bit range",
			record:    `{"type":"event","key":"k","time":999,"value":9223372036854775808,"partition":1}`,
			wantField: `"value"`,
			wantCause: `field "value" integer out of signed 64-bit range: 9223372036854775808`,
		},
		{
			name:      "value below signed 64-bit range",
			record:    `{"type":"event","key":"k","time":999,"value":-9223372036854775809,"partition":1}`,
			wantField: `"value"`,
			wantCause: `field "value" integer out of signed 64-bit range: -9223372036854775809`,
		},
		{
			name:      "partition missing with legal value",
			record:    `{"type":"event","key":"k","time":999,"value":1}`,
			wantField: `"partition"`,
			wantCause: `missing required integer field "partition"`,
		},
		{
			name:      "partition out of configured range with legal value",
			record:    `{"type":"event","key":"k","time":999,"value":1,"partition":9}`,
			wantField: `"partition"`,
			wantCause: `field "partition" must be an integer in range [0,2), got 9`,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			lines := append(lateFieldOrderPrefix(), tc.record)
			lines = append(lines, lateFieldOrderSuffix()...)
			stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)

			if err == nil {
				t.Fatalf("an invalid late record must fail fatally; got nil, stdout=%q stderr=%q", stdout, stderr)
			}
			var inputErr *InputError
			if !errors.As(err, &inputErr) {
				t.Fatalf("want *InputError, got %T: %v", err, err)
			}
			var outputErr *OutputError
			if errors.As(err, &outputErr) {
				t.Fatalf("a malformed record must not be reported as an output failure: %v", err)
			}
			// Blank lines 1 and 5 still occupy physical numbers.
			if inputErr.Line != 6 {
				t.Errorf("InputError.Line = %d, want 6 (blank physical lines count)", inputErr.Line)
			}
			if !strings.Contains(inputErr.Reason, tc.wantField) {
				t.Errorf("reason %q must name field %s", inputErr.Reason, tc.wantField)
			}
			if !strings.Contains(inputErr.Reason, tc.wantCause) {
				t.Errorf("reason %q must state the concrete cause %q", inputErr.Reason, tc.wantCause)
			}
			// The record never reached window accumulation: it must not be
			// mislabelled as a cumulative sum overflow, and the physical line
			// must carry the field error rather than anything window-shaped.
			if strings.Contains(inputErr.Reason, "cumulative sum overflow") ||
				strings.Contains(inputErr.Reason, "window [") {
				t.Errorf("a field error below the watermark must not be blamed on window accumulation: %q", inputErr.Reason)
			}
			if strings.Contains(err.Error(), "late event") {
				t.Errorf("an invalid record must not be described as a late-event skip: %q", err.Error())
			}

			// No late notice for the bad record itself nor for the dead line 8.
			if stderr != "" {
				t.Errorf("late log must stay empty when the record itself is invalid; got %q", stderr)
			}
			// The fully written [0,1000) result stays exactly as published; the
			// still-open [600,1600) is not flushed and line 9 never closes it.
			if stdout != lateFieldOrderWantFirstWindow {
				t.Errorf("window output mismatch:\n got: %q\nwant: %q", stdout, lateFieldOrderWantFirstWindow)
			}
		})
	}
}

// TestSlidingPartitionValidLateRecordSkipsWithoutSumError is the control for
// the cases above: the same history and the same physical line 6, but the
// record's fields are all legal. It is judged against the effective watermark
// 1000 (partition 0 is already at 5000 and must not substitute that), and the
// open [600,1600) already holds math.MaxInt64, so its value 1 would overflow
// the cumulative sum if it were ever added. The late check wins: exactly one
// notice naming line 6, time 999 and watermark 1000 is written, processing
// continues, and no window count or sum changes due to that event. A legal
// event at time exactly 1000 then joins [600,1600) (value 0 moves only the
// count); repeating partition 0's watermark 5000 closes nothing, and the
// minimum watermark reaching 1600 emits the correct totals.
func TestSlidingPartitionValidLateRecordSkipsWithoutSumError(t *testing.T) {
	const M = math.MaxInt64
	lines := []string{
		``, // line 1 blank
		// Enters [0,1000) and [600,1600); both accumulate to MaxInt64.
		`{"type":"event","key":"big","time":900,"value":9223372036854775807,"partition":0}`, // line 2
		`{"type":"watermark","time":5000,"partition":0}`,                                    // line 3: fast partition ahead
		`{"type":"watermark","time":1000,"partition":1}`,                                    // line 4: effective 1000
		``, // line 5 blank
		// Fields legal; 999 < effective 1000 although 999 is inside the open
		// [600,1600), and value 1 would take that window's MaxInt64 over the
		// top. It must be skipped with one notice, never a sum error.
		`{"type":"event","key":"big","time":999,"value":1,"partition":1}`, // line 6 late
		// Time exactly equal to the effective watermark: not late, joins the
		// only window containing 1000, [600,1600); value 0 moves count only.
		`{"type":"event","key":"big","time":1000,"value":0,"partition":1}`, // line 7
		`{"type":"watermark","time":5000,"partition":0}`,                   // line 8: min stays 1000, closes nothing
		`{"type":"watermark","time":1600,"partition":1}`,                   // line 9: min = 1600 closes [600,1600)
	}
	stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
	if err != nil {
		t.Fatalf("a legal late event must skip, not fail even at the sum boundary: %v", err)
	}
	wantNotice := "line 6: late event time=999 below current watermark 1000, skipped\n"
	if stderr != wantNotice {
		t.Fatalf("late notice mismatch:\n got: %q\nwant: %q", stderr, wantNotice)
	}
	// The notice judges against the effective minimum, never p0's own 5000.
	if strings.Count(stderr, "skipped\n") != 1 {
		t.Errorf("late event must be reported exactly once, got %q", stderr)
	}
	if strings.Contains(stderr, "5000") {
		t.Errorf("latency must be judged by the effective watermark 1000, not the fast partition's 5000: %q", stderr)
	}
	want := strings.Join([]string{
		`{"key":"big","start":0,"end":1000,"count":1,"sum":9223372036854775807}`,
		// The skipped event added neither count nor value; the time==1000 event
		// moved only the count, and the sum rests exactly on MaxInt64.
		`{"key":"big","start":600,"end":1600,"count":2,"sum":9223372036854775807}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("window output mismatch:\n got: %q\nwant: %q", stdout, want)
	}
	// Reparse to pin the exact signed 64-bit totals the notices must not touch.
	got := decodeAggregateResults(t, stdout)
	wantRows := []AggregateResult{
		{Key: "big", Start: 0, End: 1000, Count: 1, Sum: M},
		{Key: "big", Start: 600, End: 1600, Count: 2, Sum: M},
	}
	if len(got) != len(wantRows) {
		t.Fatalf("got %d rows, want %d: %v", len(got), len(wantRows), got)
	}
	for i := range wantRows {
		if got[i] != wantRows[i] {
			t.Errorf("row %d = %+v, want %+v", i, got[i], wantRows[i])
		}
	}
}

// TestSlidingPartitionInvalidLateRecordControlIsActuallyLate proves the
// history used above genuinely sits below the watermark: with the bad field
// repaired, the line-6 record is skipped as a normal late event exactly once
// and aggregation proceeds, closing [600,1600) later on the legitimate
// contributions alone (count 2, sum 10 -- the skipped value 1 adds nothing).
func TestSlidingPartitionInvalidLateRecordControlIsActuallyLate(t *testing.T) {
	lines := append(lateFieldOrderPrefix(),
		`{"type":"event","key":"k","time":999,"value":1,"partition":1}`, // line 6: same shape, now valid
	)
	lines = append(lines, lateFieldOrderSuffix()...)
	stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
	if err != nil {
		t.Fatalf("control record is valid and must not fail: %v", err)
	}
	wantNotices := strings.Join([]string{
		"line 6: late event time=999 below current watermark 1000, skipped",
		"line 8: late event time=998 below current watermark 1000, skipped",
		"",
	}, "\n")
	if stderr != wantNotices {
		t.Fatalf("late notices mismatch:\n got: %q\nwant: %q", stderr, wantNotices)
	}
	want := strings.Join([]string{
		`{"key":"k","start":0,"end":1000,"count":1,"sum":7}`,
		// line 2's 7 and line 7's time==watermark 3; the late lines add
		// nothing: count 2 / sum 10.
		`{"key":"k","start":600,"end":1600,"count":2,"sum":10}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("window output mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

package edgefleet

import (
	"errors"
	"strings"
	"testing"
)

// Shared fixture for the idle-resume regression: window 1000, slide 600, two
// partitions, one key. Partition 0's event at 700 lands in both [0,1000) and
// [600,1600); partition 1's event at 1000 lands only in [600,1600). After
// partition 0 reports 2000 and partition 1 reports 1000 the effective
// watermark is 1000, so only [0,1000) closes (count 1, sum 2) while
// [600,1600) keeps both partitions' contributions. The blank physical lines
// 5 and 7 count toward line numbers but carry no record.
func slidingIdleResumeFixtureLines() []string {
	return []string{
		`{"type":"event","key":"sensor-a","time":700,"value":2,"partition":0}`,  // line 1
		`{"type":"event","key":"sensor-a","time":1000,"value":3,"partition":1}`, // line 2
		`{"type":"watermark","time":2000,"partition":0}`,                        // line 3: p0 ahead, effective still unknown
		`{"type":"watermark","time":1000,"partition":1}`,                        // line 4: effective = 1000, closes [0,1000)
		``, // line 5: blank, counts toward physical line numbers
		`{"type":"idle","partition":0}`, // line 6: p0 idle; p1 keeps effective at 1000
		``,                              // line 7: blank
	}
}

// A resume watermark that is above the current effective watermark but below
// the partition's own pre-idle watermark must still be rejected: the resume
// record has to clear both lower bounds. The error is the existing input
// error naming the physical line (blank lines count), partition 0 and the
// violated previous-watermark bound, not a late-event notice. The window
// already closed before the failed resume stays output, and watermarks after
// the failed record are never processed, so they cannot close [600,1600).
func TestAggregateSlidingIdleResumeBelowOwnOldWatermark(t *testing.T) {
	lines := append(slidingIdleResumeFixtureLines(),
		`{"type":"watermark","time":1600,"partition":0}`, // line 8: 1600 > effective 1000 but < p0's old 2000
		`{"type":"watermark","time":1600,"partition":1}`, // line 9: must never run (would close [600,1600))
	)
	stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)

	var inputErr *InputError
	if err == nil {
		t.Fatal("expected an input error for the too-low resume record, got nil")
	}
	if !errors.As(err, &inputErr) {
		t.Fatalf("expected *InputError, got %T: %v", err, err)
	}
	if inputErr.Line != 8 {
		t.Errorf("Line = %d, want 8 (blank physical lines 5 and 7 count)", inputErr.Line)
	}
	// The violated bound is the partition's own previous watermark, even
	// though 1600 is already past the effective watermark 1000.
	for _, sub := range []string{
		"resume watermark 1600",
		"partition 0",
		"previous watermark 2000",
	} {
		if !strings.Contains(inputErr.Reason, sub) {
			t.Errorf("reason = %q, want substring %q", inputErr.Reason, sub)
		}
	}
	if strings.Contains(inputErr.Reason, "effective watermark") {
		t.Errorf("the effective-watermark bound must not be the reported one: %q", inputErr.Reason)
	}

	// The failure must not be downgraded to a late-event notice.
	if stderr != "" {
		t.Errorf("a rejected resume record must produce no late-event notice, got %q", stderr)
	}
	// The fully emitted window stays; the still-open window is neither
	// emitted by the failed record nor closed by the watermark after it.
	want := `{"key":"sensor-a","start":0,"end":1000,"count":1,"sum":2}` + "\n"
	if stdout != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

// Resuming exactly at the partition's own previous watermark is legal even
// though it sits far above the effective watermark: it must not by itself
// close [600,1600) or re-emit [0,1000), because partition 1 still pins the
// effective watermark at 1000. Events after the resume are judged against the
// effective watermark, so the event at 1000 is counted normally rather than
// skipped as late against partition 0's own 2000. The merged window closes
// only once partition 1 advances to 1600 (count 3, sum 9, no partition
// field), and windows still open at end of input are not flushed.
func TestAggregateSlidingIdleResumeAtOwnOldWatermark(t *testing.T) {
	lines := append(slidingIdleResumeFixtureLines(),
		`{"type":"watermark","time":2000,"partition":0}`,                        // line 8: resume at the old watermark; effective stays 1000
		`{"type":"event","key":"sensor-a","time":1000,"value":4,"partition":0}`, // line 9: not late (1000 >= effective 1000)
		`{"type":"watermark","time":1600,"partition":1}`,                        // line 10: effective = 1600, closes [600,1600)
		`{"type":"event","key":"sensor-a","time":2000,"value":5,"partition":0}`, // line 11: opens [1200,2200), [1800,2800); stays open
	)
	stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("unexpected stderr: %q", stderr)
	}
	want := strings.Join([]string{
		`{"key":"sensor-a","start":0,"end":1000,"count":1,"sum":2}`,
		// Resume at 2000 emits nothing; the window closes only when
		// partition 1 catches up, merging both pre-idle events with the
		// post-resume one. The result carries no partition field.
		`{"key":"sensor-a","start":600,"end":1600,"count":3,"sum":9}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

package edgefleet

import (
	"strconv"
	"strings"
	"testing"
)

// Regression safeguards for the interaction between idle declarations and the
// effective (minimum) watermark when several active partitions tie on the
// minimum in partitioned sliding mode (window 1000, slide 600, three
// partitions, one key "k"):
//
//   - With the per-partition watermarks 1600/600/600 the effective watermark
//     is 600 and no window has closed. Declaring ONE of the two slow
//     partitions idle must not advance the effective watermark: the other,
//     still-active partition still pins it at 600, so no window may close
//     early. Only when that last holder of the minimum declares idle does the
//     remaining partition's 1600 become the effective watermark and close the
//     windows.
//   - While one minimum holder is idle, a legal event arriving from the other,
//     still-active minimum holder (time 1000, equal to the would-be window
//     edge and well above the effective 600) is judged against the effective
//     watermark 600 -- never against the fast partition's own 1600 -- so it is
//     neither reported late nor dropped; it joins the still-open overlapping
//     window.
//   - The window that closes last keeps the events both partitions
//     contributed before they went idle. The event at 1300 also belongs to
//     [1200,2200), which stays open at end of input and is never flushed.
//   - The rule is symmetric in which of the two tied partitions idles first,
//     and a repeated idle declaration for an already-idle partition is a
//     no-op: it neither advances the watermark nor re-emits any result while
//     the other slow partition stays active.
//
// Every check goes through the public RunAggregatePartitionedSliding entry
// point; output stays the existing line-per-JSON format with no partition
// field, and the normal path produces neither late notices nor errors.

// tiedMinIdleBaseLines is the shared history physical lines 1-6:
//
//	line 1: p0 event time=700  value=2 -> [0,1000) and [600,1600)
//	line 2: p1 event time=1000 value=3 -> [600,1600)
//	line 3: p2 event time=1300 value=5 -> [600,1600) and [1200,2200)
//	line 4: p0 watermark 1600           -> fast partition races ahead
//	line 5: p1 watermark 600
//	line 6: p2 watermark 600            -> effective min = 600; nothing closes
//
// Windows in play start at 0, 600, 1200, ... with length 1000.
func tiedMinIdleBaseLines() []string {
	return []string{
		`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,
		`{"type":"event","key":"k","time":1000,"value":3,"partition":1}`,
		`{"type":"event","key":"k","time":1300,"value":5,"partition":2}`,
		`{"type":"watermark","time":1600,"partition":0}`,
		`{"type":"watermark","time":600,"partition":1}`,
		`{"type":"watermark","time":600,"partition":2}`,
	}
}

// tiedMinIdleWantOutput is the exact, order-pinned output the full sequence
// must produce, with no partition field:
//
//   - [0,1000) holds only partition 0's time=700 event (the time=1000 events
//     sit on the right edge and must not leak back): count 1, sum 2.
//   - [600,1600) keeps both idle partitions' pre-idle contributions (2 from
//     p0, 3 from p1, 5 from p2) plus the still-active holder's legal event
//     after the first idle declaration (4): count 4, sum 14.
//
// [1200,2200) (holding the time=1300 event, count 1, sum 5) is not among the
// rows: it is still open when input ends.
var tiedMinIdleWantOutput = strings.Join([]string{
	`{"key":"k","start":0,"end":1000,"count":1,"sum":2}`,
	`{"key":"k","start":600,"end":1600,"count":4,"sum":14}`,
	``,
}, "\n")

// TestSlidingPartitionTiedMinWatermarkNoClosureBeforeLastHolderIdles pins the
// output timing: after the three watermarks establish 600 as the effective
// minimum, neither that state nor the first idle declaration (nor repeated
// declarations of the same already-idle partition) may close any window,
// because the other slow partition is still active at 600. A legal event from
// that still-active partition after the first idle declaration is accepted
// with no late notice even though partition 0's own watermark is 1600.
func TestSlidingPartitionTiedMinWatermarkNoClosureBeforeLastHolderIdles(t *testing.T) {
	cases := []struct {
		name      string
		firstIdle int64 // the slow partition that declares idle first (1 or 2)
		active    int64 // the other slow partition, still active at 600
	}{
		{name: "partition 1 idles first, partition 2 holds the minimum", firstIdle: 1, active: 2},
		{name: "partition 2 idles first, partition 1 holds the minimum", firstIdle: 2, active: 1},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			lines := tiedMinIdleBaseLines()
			lines = append(lines,
				`{"type":"idle","partition":`+pid(tc.firstIdle)+`}`,
				// Repeating the already-idle declaration must stay a no-op.
				`{"type":"idle","partition":`+pid(tc.firstIdle)+`}`,
				`{"type":"idle","partition":`+pid(tc.firstIdle)+`}`,
				// time 1000 >= effective 600: legal, joins [600,1600), closes
				// nothing. It must not be judged late against p0's own 1600.
				`{"type":"event","key":"k","time":1000,"value":4,"partition":`+pid(tc.active)+`}`,
			)
			stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 3)
			if err != nil {
				t.Fatalf("unexpected error while the last minimum holder stays active: %v", err)
			}
			if stderr != "" {
				t.Errorf("the active holder's time=1000 event must not be late vs effective 600, got notice %q", stderr)
			}
			if stdout != "" {
				t.Errorf("no window may close while active partition %d still pins the effective watermark at 600, got output %q", tc.active, stdout)
			}
		})
	}
}

// TestSlidingPartitionTiedMinWatermarkIdleSequence is the primary scenario:
// once the second (last active) holder of the minimum declares idle,
// partition 0's 1600 becomes the effective watermark and closes [0,1000) and
// [600,1600) in that order with the merged counts and sums, preserving the
// events both partitions contributed before idling. [1200,2200) stays open at
// end of input. The whole run produces no late notice and no error.
func TestSlidingPartitionTiedMinWatermarkIdleSequence(t *testing.T) {
	lines := tiedMinIdleBaseLines()
	lines = append(lines,
		`{"type":"idle","partition":1}`,                                  // p1 leaves; p2 still active at 600
		`{"type":"event","key":"k","time":1000,"value":4,"partition":2}`, // legal: joins [600,1600)
		`{"type":"idle","partition":2}`,                                  // last minimum holder leaves: effective = 1600
	)
	stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 3)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("normal processing must produce no late notice, got %q", stderr)
	}
	if stdout != tiedMinIdleWantOutput {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, tiedMinIdleWantOutput)
	}

	// Pin the exact rows as structured values, and make sure the still-open
	// [1200,2200) window (which holds the time=1300 event) is never emitted.
	got := decodeAggregateResults(t, stdout)
	wantRows := []AggregateResult{
		{Key: "k", Start: 0, End: 1000, Count: 1, Sum: 2},
		{Key: "k", Start: 600, End: 1600, Count: 4, Sum: 14},
	}
	if len(got) != len(wantRows) {
		t.Fatalf("got %d rows, want %d (no [1200,2200) flush at end of input): %v", len(got), len(wantRows), got)
	}
	for i := range wantRows {
		if got[i] != wantRows[i] {
			t.Errorf("row %d = %+v, want %+v", i, got[i], wantRows[i])
		}
	}
}

// TestSlidingPartitionTiedMinWatermarkIdleOrderSymmetric proves both holders
// of the tied minimum obey the same rule regardless of which one declares
// idle first: the legal event after the first declaration is sent by the
// partition that remains active, and the second declaration is what finally
// lets partition 0's 1600 close the windows. Both orderings yield the same two
// result lines, no other output, and no late notices.
func TestSlidingPartitionTiedMinWatermarkIdleOrderSymmetric(t *testing.T) {
	cases := []struct {
		name       string
		firstIdle  int64
		secondIdle int64
		active     int64 // sends the legal time=1000 event between the two declarations
	}{
		{name: "p1 idles then active p2 contributes then idles", firstIdle: 1, secondIdle: 2, active: 2},
		{name: "p2 idles then active p1 contributes then idles", firstIdle: 2, secondIdle: 1, active: 1},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			lines := tiedMinIdleBaseLines()
			lines = append(lines,
				`{"type":"idle","partition":`+pid(tc.firstIdle)+`}`,
				`{"type":"event","key":"k","time":1000,"value":4,"partition":`+pid(tc.active)+`}`,
				`{"type":"idle","partition":`+pid(tc.secondIdle)+`}`,
			)
			stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 3)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if stderr != "" {
				t.Fatalf("normal processing must produce no late notice, got %q", stderr)
			}
			if stdout != tiedMinIdleWantOutput {
				t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, tiedMinIdleWantOutput)
			}
		})
	}
}

// TestSlidingPartitionTiedMinRepeatedIdleNeverAdvancesWatermark combines the
// no-op guarantee with the timing guarantee: after partition 1 idles, further
// idle declarations for the same already-idle partition 1 must neither close
// windows nor duplicate results while partition 2 still holds the minimum at
// 600. The active holder's time=1000 event still aggregates normally, and the
// single later idle declaration for partition 2 is the one record that closes
// the windows -- exactly once each.
func TestSlidingPartitionTiedMinRepeatedIdleNeverAdvancesWatermark(t *testing.T) {
	lines := tiedMinIdleBaseLines()
	lines = append(lines,
		`{"type":"idle","partition":1}`,
		`{"type":"idle","partition":1}`, // repeated: still-active p2 keeps effective 600
		`{"type":"idle","partition":1}`, // repeated again: same no-op
		`{"type":"event","key":"k","time":1000,"value":4,"partition":2}`,
		`{"type":"idle","partition":2}`, // last minimum holder leaves: closes both windows
		`{"type":"idle","partition":2}`, // repeated after closure: must not re-emit
	)
	stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 3)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("normal processing must produce no late notice, got %q", stderr)
	}
	if stdout != tiedMinIdleWantOutput {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, tiedMinIdleWantOutput)
	}
	// Each window appears exactly once: a repeated idle declaration must never
	// add or duplicate a result line.
	if n := strings.Count(stdout, `"start":0,"end":1000`); n != 1 {
		t.Errorf("[0,1000) emitted %d times, want exactly 1", n)
	}
	if n := strings.Count(stdout, `"start":600,"end":1600`); n != 1 {
		t.Errorf("[600,1600) emitted %d times, want exactly 1", n)
	}
	if strings.Contains(stdout, `"start":1200`) {
		t.Errorf("[1200,2200) is still open at end of input and must never be emitted: %q", stdout)
	}
}

// pid formats a partition index for embedding in a JSON record.
func pid(p int64) string {
	return strconv.FormatInt(p, 10)
}

